<template><section class="page"><div class="heading"><div><p> CUSTOMER INTELLIGENCE</p><h1>顧客分析</h1><small>RFM は購入金額・注文頻度・最終購入日を各 1〜5 点で評価した合計スコアです。</small></div><el-input v-model="draft" placeholder="名前・メールで検索" @keyup.enter="search"><template #append><el-button @click="search">検索</el-button></template></el-input></div><div class="metrics"><article><span>新規顧客</span><strong>{{ summary?.newCustomerCount ?? 0 }}</strong><small>直近30日に登録</small></article><article><span>平均消費額</span><strong>{{ money(summary?.averageSpend??0) }}</strong><small>支払い済み注文ベース</small></article><article><span>復購率</span><strong>{{ (summary?.repeatPurchaseRate??0).toFixed(1) }}%</strong><small>2回以上購入した顧客の割合</small></article></div><div class="grid"><article class="surface"><h2>新規顧客の推移</h2><MetricLineChart v-if="growth.length" :data="growth.map(x=>({date:x.date,value:x.newCustomers}))" title="新規顧客の推移" :formatter="v=>String(v)" /><div v-else class="empty">データなし</div></article><article class="surface"><h2>顧客構成</h2><div class="ratio"><strong>{{ summary?.newCustomerCount??0 }}</strong> 新規 <i/> <strong>{{ summary?.existingCustomerCount??0 }}</strong> 既存</div><h3>会員レベル</h3><ul><li v-for="x in summary?.memberLevelDistribution" :key="x.label"><span>{{ x.label }}</span><b>{{ x.count }}</b></li></ul><h3>性別</h3><ul><li v-for="x in summary?.genderDistribution" :key="x.label"><span>{{ x.label }}</span><b>{{ x.count }}</b></li></ul></article></div><div class="grid"><article class="surface"><h2>年齢層分布</h2><ul><li v-for="x in summary?.ageDistribution" :key="x.label"><span>{{ x.label }}</span><b>{{ x.count }}</b></li></ul></article><article class="surface"><h2>高価値顧客 Top 10</h2><ol><li v-for="x in highValue" :key="x.id"><span>{{ x.name }}</span><small>{{ x.orderCount }}件 / RFM {{ x.rfmScore }}</small><b>{{ money(x.totalSpend) }}</b></li></ol></article></div><article class="surface"><h2>顧客データ</h2><el-table :data="customers" v-loading="loading" class="table" size="small"><el-table-column prop="name" label="顧客" min-width="120"/><el-table-column prop="email" label="メール" min-width="180"/><el-table-column prop="region" label="地域"/><el-table-column prop="memberLevel" label="会員"/><el-table-column label="消費額" align="right"><template #default="s">{{money(s.row.totalSpend)}}</template></el-table-column><el-table-column prop="orderCount" label="注文数" align="right"/></el-table><el-pagination v-model:current-page="page" :page-size="10" layout="total,prev,pager,next" :total="total" @current-change="loadCustomers"/></article></section></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import MetricLineChart from '../components/charts/MetricLineChart.vue';import {getCustomerList,getCustomerSummary,getHighValueCustomers,getCustomerGrowth} from '../api/dashboard';import type {CustomerListItem,CustomerSummary,HighValueCustomer} from '../types/dashboard';const summary=ref<CustomerSummary>();const highValue=ref<HighValueCustomer[]>([]);const growth=ref<{date:string;newCustomers:number}[]>([]);const customers=ref<CustomerListItem[]>([]);const total=ref(0);const page=ref(1);const draft=ref('');const searchText=ref('');const loading=ref(false);const money=(v:number)=>new Intl.NumberFormat('ja-JP',{style:'currency',currency:'JPY',maximumFractionDigits:0}).format(v);async function loadCustomers(){loading.value=true;try{const r=await getCustomerList({search:searchText.value||undefined,page:page.value,pageSize:10});customers.value=r.items;total.value=r.total}finally{loading.value=false}}function search(){searchText.value=draft.value;page.value=1;void loadCustomers()}onMounted(async()=>{const r=await Promise.all([getCustomerSummary(),getHighValueCustomers(),getCustomerGrowth({startDate:'2026-01-01',endDate:'2026-07-26'},'day')]);summary.value=r[0];highValue.value=r[1];growth.value=r[2];await loadCustomers()})</script>
<style scoped>.page{padding-top:22px}.heading{display:flex;justify-content:space-between;align-items:end;margin:22px 0;gap:20px}.heading p{color:#4bc9f7;font-size:11px;letter-spacing:.14em}.heading h1{margin:8px 0;color:#eff8ff}.heading small{color:#829db6}.metrics,.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.grid{grid-template-columns:1.2fr .8fr;margin-top:16px}.surface,.metrics article{padding:20px;border:1px solid rgba(125,181,230,.13);border-radius:13px;background:linear-gradient(135deg,rgba(24,50,82,.88),rgba(14,30,53,.88))}.metrics span,.metrics small{color:#819bb4;font-size:12px}.metrics strong{display:block;margin:12px 0;color:#ecf7ff;font-size:25px}.surface h2{margin:0 0 16px;color:#eaf4fc;font-size:15px}.surface h3{margin:16px 0 6px;color:#9bb5ca;font-size:12px}.surface ul,.surface ol{margin:0;padding:0;list-style:none}.surface li{display:flex;gap:10px;padding:8px 0;border-bottom:1px solid rgba(126,174,218,.1);color:#bfd3e3;font-size:12px}.surface li b{margin-left:auto;color:#e1eff9}.surface li small{color:#7894ad}.ratio{color:#93acc1;font-size:12px}.ratio strong{color:#63d1fa;font-size:18px}.ratio i{display:inline-block;width:1px;height:16px;margin:0 8px;background:#55728d}.table{width:100%;--el-table-bg-color:transparent;--el-table-tr-bg-color:transparent;--el-table-text-color:#bfd3e3;--el-table-header-bg-color:rgba(44,89,130,.14);--el-table-border-color:rgba(126,174,218,.1)}.el-pagination{justify-content:flex-end;margin-top:14px}@media(max-width:800px){.heading{align-items:start;flex-direction:column}.metrics,.grid{grid-template-columns:1fr}}</style>
